import"./chunk-VC46IEJQ.js";var a=(r,s)=>({en:r,zh:s}),e=(r,s,o,i,n,l,d,h,t)=>({name:a(...r),desc:a(...s),tour:a(...o),...t?{spoiler:a(...t)}:{},source:{confidence:i,refs:n,book:a(...l),unknown:a(...d),interpretation:a(...h)}}),p={id:"astapor",intro:{en:"The southernmost of the three Slaver cities, an old city of red brick on Slaver's Bay. Its stepped pyramids belong to the Good Masters, whose wealth rests on the Unsullied they train and sell.",zh:"\u5974\u96B6\u6E7E\u4E09\u5EA7\u5974\u96B6\u57CE\u90A6\u4E2D\u6700\u5357\u7684\u4E00\u5EA7\uFF0C\u662F\u4E00\u5EA7\u53E4\u8001\u7684\u7EA2\u7816\u4E4B\u57CE\u3002\u57CE\u4E2D\u7684\u9636\u68AF\u91D1\u5B57\u5854\u5C5E\u4E8E\u5584\u4E3B\uFF0C\u4ED6\u4EEC\u7684\u8D22\u5BCC\u5168\u7CFB\u4E8E\u8BAD\u7EC3\u5E76\u51FA\u552E\u65E0\u57A2\u8005\u3002"},notes:{en:'From the books: the red brick (the "Red City"), the Good Masters, stepped pyramids including those of Nakloz and Ullhor, the Plaza of Pride with its bronze harpy fountain, the Unsullied trade, and a harbour gate topped by an old crumbling harpy. Invented here: the oval plan, street grid, number and position of pyramids, the training yards, a separate market, and every building shape.',zh:"\u4E66\u4E2D\u53EF\u636E\uFF1A\u7EA2\u7816\uFF08\u6545\u79F0\u201C\u7EA2\u57CE\u201D\uFF09\u3001\u5584\u4E3B\u3001\u9636\u68AF\u91D1\u5B57\u5854\uFF08\u5305\u62EC\u7EB3\u514B\u6D1B\u5179\u4E0E\u4E4C\u5C14\u970D\u4E24\u5BB6\uFF09\u3001\u7ACB\u6709\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u55B7\u6CC9\u7684\u9A84\u50B2\u5E7F\u573A\u3001\u65E0\u57A2\u8005\u4EA4\u6613\uFF0C\u4EE5\u53CA\u9876\u4E0A\u7ACB\u7740\u4E00\u5C0A\u6B8B\u7834\u9E70\u8EAB\u5973\u5996\u7684\u6E2F\u53E3\u57CE\u95E8\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u692D\u5706\u5F62\u57CE\u5E02\u5E73\u9762\u3001\u8857\u9053\u7F51\u683C\u3001\u91D1\u5B57\u5854\u7684\u6570\u91CF\u4E0E\u4F4D\u7F6E\u3001\u8BAD\u7EC3\u573A\u3001\u72EC\u7ACB\u5E02\u573A\uFF0C\u4EE5\u53CA\u5168\u90E8\u5EFA\u7B51\u9020\u578B\u3002"},tour:["harbour","harbour-gate","red-walls","plaza-of-pride","harpy-fountain","pyramid-of-nakloz","unsullied-pits","slave-market","brick-warrens"],sources:[{ref:"asos",checked:"memory",note:a("Astapor appears in Daenerys's chapters of A Storm of Swords; recalled, not re-read.","\u963F\u65AF\u5854\u6CE2\u89C1\u4E8E\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\u4E2D\u4E39\u59AE\u8389\u4E1D\u7684\u7AE0\u8282\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002")},{ref:"awoiaf",checked:"search-snippet",note:a("Search summaries of the wiki: red brick throughout, the pyramids of Nakloz and Ullhor, an old crumbling harpy on the harbour gate, and the Astapori harpy (woman's torso, bat wings, eagle legs, scorpion tail, a chain of open manacles in its talons). Pages could not be fetched.","\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u5168\u57CE\u7686\u7528\u7EA2\u7816\uFF1B\u7EB3\u514B\u6D1B\u5179\u4E0E\u4E4C\u5C14\u970D\u7684\u91D1\u5B57\u5854\uFF1B\u6E2F\u53E3\u57CE\u95E8\u4E0A\u4E00\u5C0A\u53E4\u65E7\u6B8B\u7834\u7684\u9E70\u8EAB\u5973\u5996\uFF1B\u963F\u65AF\u5854\u6CE2\u7684\u9E70\u8EAB\u5973\u5996\u5F62\u8C61\uFF08\u5973\u4EBA\u4E0A\u8EAB\u3001\u8760\u7FFC\u3001\u9E70\u8DB3\u3001\u874E\u5C3E\uFF0C\u722A\u63E1\u4E00\u4E32\u6253\u5F00\u7684\u9563\u94D0\uFF09\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002")},{ref:"twoiaf",checked:"not-accessed",note:a("Companion background on the Slaver cities was not consulted.","\u672A\u67E5\u9605\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u4E2D\u5173\u4E8E\u5974\u96B6\u57CE\u90A6\u7684\u80CC\u666F\u8D44\u6599\u3002")}],landmarks:{"plaza-of-pride":e(["Plaza of Pride","\u9A84\u50B2\u5E7F\u573A"],["Astapor's great brick square, where the Unsullied are drawn up for buyers to inspect.","\u963F\u65AF\u5854\u6CE2\u7684\u7EA2\u7816\u5927\u5E7F\u573A\uFF0C\u65E0\u57A2\u8005\u5728\u6B64\u5217\u961F\uFF0C\u4F9B\u4E70\u4E3B\u68C0\u9605\u3002"],["In the Plaza of Pride, ranks of Unsullied stand motionless under the sun for the buyers.","\u9A84\u50B2\u5E7F\u573A\u4E0A\uFF0C\u4E00\u6392\u6392\u65E0\u57A2\u8005\u5728\u70C8\u65E5\u4E0B\u7EB9\u4E1D\u4E0D\u52A8\uFF0C\u4EFB\u4E70\u4E3B\u5BA1\u89C6\u3002"],"high",["asos","awoiaf"],["A large plaza with a harpy fountain at its centre, where Daenerys inspects and buys the Unsullied.","\u4E00\u5EA7\u5927\u5E7F\u573A\uFF0C\u4E2D\u592E\u6709\u9E70\u8EAB\u5973\u5996\u55B7\u6CC9\uFF1B\u4E39\u59AE\u8389\u4E1D\u5728\u6B64\u68C0\u9605\u5E76\u4E70\u4E0B\u65E0\u57A2\u8005\u3002"],["Its exact size and the buildings around it.","\u786E\u5207\u5927\u5C0F\u53CA\u56DB\u5468\u5EFA\u7B51\u3002"],["Paving, corner posts and braziers are invented; pyramids frame it by choice.","\u94FA\u5730\u3001\u89D2\u67F1\u4E0E\u706B\u76C6\u5747\u4E3A\u81EA\u62DF\uFF1B\u4EE5\u91D1\u5B57\u5854\u73AF\u7ED5\u5E7F\u573A\u662F\u672C\u573A\u666F\u7684\u5B89\u6392\u3002"]),"harpy-fountain":e(["Harpy Fountain","\u9E70\u8EAB\u5973\u5996\u55B7\u6CC9"],["A red-brick fountain crowned by a great bronze harpy, emblem of Old Ghis.","\u4E00\u5EA7\u7EA2\u7816\u55B7\u6CC9\uFF0C\u9876\u4E0A\u7ACB\u7740\u5DE8\u5927\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\uFF0C\u90A3\u662F\u53E4\u5409\u65AF\u7684\u5FBD\u8BB0\u3002"],["The bronze harpy of Ghis, chains in her talons, presides over the trade in men.","\u5409\u65AF\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\u722A\u63E1\u9563\u94D0\uFF0C\u4FEF\u89C6\u7740\u8FD9\u573A\u4EBA\u53E3\u4E70\u5356\u3002"],"high",["asos","awoiaf"],["A fountain in the plaza whose water smells of brimstone, with a bronze harpy about twenty feet tall at its centre; the Astapori harpy holds a chain of open manacles.","\u5E7F\u573A\u4E0A\u7684\u55B7\u6CC9\uFF0C\u6C34\u6709\u786B\u78FA\u5473\uFF0C\u4E2D\u592E\u7ACB\u7740\u7EA6\u4E8C\u5341\u5C3A\u9AD8\u7684\u9752\u94DC\u9E70\u8EAB\u5973\u5996\uFF1B\u963F\u65AF\u5854\u6CE2\u7684\u9E70\u8EAB\u5973\u5996\u722A\u63E1\u4E00\u4E32\u6253\u5F00\u7684\u9563\u94D0\u3002"],["The fountain's exact shape and the statue's pose.","\u55B7\u6CC9\u7684\u786E\u5207\u5F62\u72B6\u4E0E\u96D5\u50CF\u7684\u59FF\u6001\u3002"],["The figure is drawn a little over twenty feet for legibility; its pose is invented.","\u4E3A\u4FBF\u4E8E\u8FA8\u8BA4\uFF0C\u96D5\u50CF\u7565\u9AD8\u4E8E\u4E8C\u5341\u5C3A\uFF1B\u59FF\u6001\u4E3A\u81EA\u62DF\u3002"]),"pyramid-of-nakloz":e(["Pyramid of Nakloz","\u7EB3\u514B\u6D1B\u5179\u91D1\u5B57\u5854"],["Seat of the house of Nakloz, to which the slaver Kraznys mo Nakloz belongs: a stepped pyramid of red brick.","\u7EB3\u514B\u6D1B\u5179\u5BB6\u65CF\u7684\u5B85\u90B8\uFF0C\u5974\u96B6\u8D29\u5B50\u514B\u62C9\u5179\u5C3C\xB7\u83AB\xB7\u7EB3\u514B\u6D1B\u5179\u5373\u51FA\u81EA\u6B64\u5BB6\uFF1A\u4E00\u5EA7\u7EA2\u7816\u9636\u68AF\u91D1\u5B57\u5854\u3002"],["Each Good Master's family lives in its own pyramid of red brick.","\u6BCF\u4E2A\u5584\u4E3B\u5BB6\u65CF\u90FD\u4F4F\u5728\u81EA\u5BB6\u7684\u7EA2\u7816\u91D1\u5B57\u5854\u91CC\u3002"],"medium",["asos","awoiaf"],["The pyramid of Nakloz is named as one of Astapor's great pyramids.","\u7EB3\u514B\u6D1B\u5179\u91D1\u5B57\u5854\u88AB\u63D0\u53CA\u4E3A\u963F\u65AF\u5854\u6CE2\u7684\u5927\u91D1\u5B57\u5854\u4E4B\u4E00\u3002"],["Height, number of tiers and position in the city.","\u9AD8\u5EA6\u3001\u5C42\u6570\u4E0E\u57CE\u4E2D\u4F4D\u7F6E\u3002"],["Six tiers with a plastered crown and dome, placed west of the plaza.","\u516D\u5C42\uFF0C\u5854\u9876\u62B9\u7070\u5E76\u8986\u5706\u9876\uFF1B\u7F6E\u4E8E\u5E7F\u573A\u4EE5\u897F\u3002"],["Kraznys dies when Daenerys turns the Unsullied on the Good Masters; the pyramid is later sacked and burned.","\u4E39\u59AE\u8389\u4E1D\u4EE4\u65E0\u57A2\u8005\u53CD\u6208\u4E00\u51FB\u65F6\uFF0C\u514B\u62C9\u5179\u5C3C\u4E27\u547D\uFF1B\u8FD9\u5EA7\u91D1\u5B57\u5854\u540E\u6765\u4E5F\u906D\u6D17\u52AB\u711A\u6BC1\u3002"]),"pyramid-of-ullhor":e(["Pyramid of Ullhor","\u4E4C\u5C14\u970D\u91D1\u5B57\u5854"],["The pyramid of another great house, set here east of the plaza.","\u53E6\u4E00\u5927\u5BB6\u65CF\u7684\u91D1\u5B57\u5854\uFF0C\u672C\u573A\u666F\u7F6E\u4E8E\u5E7F\u573A\u4EE5\u4E1C\u3002"],["Astapor is ruled by many slaving families, not by a single lord.","\u7EDF\u6CBB\u963F\u65AF\u5854\u6CE2\u7684\u662F\u4F17\u591A\u5974\u96B6\u4E3B\u5BB6\u65CF\uFF0C\u800C\u975E\u4E00\u4F4D\u541B\u4E3B\u3002"],"medium",["asos","awoiaf"],["A pyramid of Ullhor is named; the Good Master Grazdan mo Ullhor belongs to this house.","\u4E66\u4E2D\u63D0\u5230\u4E4C\u5C14\u970D\u91D1\u5B57\u5854\uFF1B\u5584\u4E3B\u683C\u62C9\u5179\u4E39\xB7\u83AB\xB7\u4E4C\u5C14\u970D\u5373\u51FA\u81EA\u6B64\u5BB6\u3002"],["Almost everything about its look and location.","\u5916\u89C2\u4E0E\u4F4D\u7F6E\u51E0\u4E4E\u4E00\u65E0\u6240\u77E5\u3002"],["Shaped like Nakloz but slightly smaller; the eastern position is invented.","\u5F62\u5236\u4EFF\u7EB3\u514B\u6D1B\u5179\u800C\u7A0D\u5C0F\uFF1B\u4E1C\u4FA7\u4F4D\u7F6E\u4E3A\u81EA\u62DF\u3002"]),"unsullied-pits":e(["Training Yards","\u65E0\u57A2\u8005\u8BAD\u7EC3\u573A"],["Walled brick yards where ranks of Unsullied drill in silence.","\u7816\u5899\u56F4\u8D77\u7684\u9662\u843D\uFF0C\u6210\u6392\u7684\u65E0\u57A2\u8005\u5728\u6B64\u9ED8\u7136\u64CD\u7EC3\u3002"],["Here boys are made into Unsullied: trained for years to know neither fear nor pain.","\u7537\u5B69\u4EEC\u5728\u8FD9\u91CC\u88AB\u70BC\u6210\u65E0\u57A2\u8005\uFF1A\u7ECF\u5E74\u8BAD\u7EC3\uFF0C\u4E0D\u77E5\u6050\u60E7\uFF0C\u4E0D\u89C9\u75DB\u82E6\u3002"],"low",["asos"],["Astapor trains and sells the Unsullied; the Good Masters describe their harsh training to Daenerys.","\u963F\u65AF\u5854\u6CE2\u8BAD\u7EC3\u5E76\u51FA\u552E\u65E0\u57A2\u8005\uFF1B\u5584\u4E3B\u5411\u4E39\u59AE\u8389\u4E1D\u8BB2\u8FF0\u4E86\u4E25\u9177\u7684\u8BAD\u7EC3\u8FC7\u7A0B\u3002"],["Where training takes place and what the grounds look like.","\u8BAD\u7EC3\u5728\u4F55\u5904\u8FDB\u884C\uFF0C\u573A\u5730\u662F\u4F55\u6A21\u6837\u3002"],["Three walled sand yards with ranks of figures; entirely invented.","\u4E09\u5EA7\u6709\u56F4\u5899\u7684\u6C99\u5730\u9662\u843D\uFF0C\u5185\u6709\u6210\u5217\u4EBA\u5F62\uFF1B\u5B8C\u5168\u81EA\u62DF\u3002"]),"slave-market":e(["Slave Market","\u5974\u96B6\u5E02\u573A"],["Awnings, auction blocks and pens where people are sold by the lot.","\u906E\u9633\u68DA\u3001\u62CD\u5356\u53F0\u4E0E\u56F4\u680F\uFF0C\u4EBA\u88AB\u6210\u6279\u51FA\u552E\u3002"],["A block for every sale: this trade built the city.","\u4E00\u7B14\u4E70\u5356\u4E00\u5EA7\u62CD\u5356\u53F0\uFF1A\u8FD9\u5EA7\u57CE\u5C31\u662F\u9760\u8FD9\u95E8\u751F\u610F\u5EFA\u8D77\u6765\u7684\u3002"],"low",["asos","awoiaf"],["Astapor is a slaving city; sales are shown in the Plaza of Pride.","\u963F\u65AF\u5854\u6CE2\u662F\u5974\u96B6\u8D38\u6613\u4E4B\u57CE\uFF1B\u4E66\u4E2D\u7684\u4E70\u5356\u53D1\u751F\u5728\u9A84\u50B2\u5E7F\u573A\u3002"],["Whether a separate market quarter exists, and where.","\u662F\u5426\u53E6\u6709\u72EC\u7ACB\u7684\u5E02\u573A\u533A\uFF0C\u53C8\u5728\u4F55\u5904\u3002"],["A separate market south-east of the plaza is an invention.","\u5E7F\u573A\u4E1C\u5357\u53E6\u8BBE\u5E02\u573A\u533A\uFF0C\u7EAF\u5C5E\u81EA\u62DF\u3002"]),"red-walls":e(["Red Walls","\u7EA2\u7816\u57CE\u5899"],["Thick, old walls of red brick, worn and crumbling.","\u539A\u91CD\u53E4\u8001\u7684\u7EA2\u7816\u57CE\u5899\uFF0C\u98CE\u5316\u5265\u843D\u3002"],["The walls are old and tired; the city trusts its Unsullied more than its masonry.","\u57CE\u5899\u53E4\u65E7\u5931\u4FEE\uFF1B\u8FD9\u5EA7\u57CE\u66F4\u501A\u4ED7\u65E0\u57A2\u8005\uFF0C\u800C\u975E\u7816\u77F3\u3002"],"medium",["asos","awoiaf"],["Astapor's walls, like the rest of the city, are of red brick, and the city is old and decaying.","\u963F\u65AF\u5854\u6CE2\u7684\u57CE\u5899\u4E0E\u5168\u57CE\u4E00\u6837\u4EE5\u7EA2\u7816\u780C\u6210\uFF0C\u57CE\u5E02\u53E4\u8001\u800C\u8870\u8D25\u3002"],["Wall height, towers and the number of gates.","\u57CE\u5899\u9AD8\u5EA6\u3001\u5854\u697C\u4E0E\u57CE\u95E8\u6570\u91CF\u3002"],["An oval circuit with stubby towers and four gates; rubble on the crest suggests decay.","\u692D\u5706\u5F62\u57CE\u5899\uFF0C\u8BBE\u77EE\u5854\u4E0E\u56DB\u5EA7\u57CE\u95E8\uFF1B\u5899\u5934\u788E\u7816\u793A\u610F\u7834\u8D25\u3002"]),"harbour-gate":e(["Harbour Gate","\u6E2F\u53E3\u57CE\u95E8"],["The sea gate, topped by an old, crumbling harpy.","\u4E34\u6D77\u7684\u57CE\u95E8\uFF0C\u9876\u4E0A\u7ACB\u7740\u4E00\u5C0A\u53E4\u65E7\u6B8B\u7834\u7684\u9E70\u8EAB\u5973\u5996\u3002"],["A crumbling harpy above the harbour gate greets every ship that docks.","\u6E2F\u53E3\u57CE\u95E8\u4E0A\uFF0C\u4E00\u5C0A\u6B8B\u7834\u7684\u9E70\u8EAB\u5973\u5996\u8FCE\u63A5\u6BCF\u4E00\u8258\u9760\u5CB8\u7684\u8239\u3002"],"medium",["asos","awoiaf"],["An old, crumbling harpy statue stands atop the harbour gate.","\u6E2F\u53E3\u57CE\u95E8\u9876\u4E0A\u7ACB\u7740\u4E00\u5C0A\u53E4\u65E7\u6B8B\u7834\u7684\u9E70\u8EAB\u5973\u5996\u50CF\u3002"],["Its material, size and pose.","\u6750\u8D28\u3001\u5C3A\u5BF8\u4E0E\u59FF\u6001\u3002"],["A large stylised harpy over a broad gatehouse on the north wall.","\u5317\u5899\u4E00\u5EA7\u5BBD\u9614\u95E8\u697C\u4E0A\u7684\u5927\u578B\u98CE\u683C\u5316\u9E70\u8EAB\u5973\u5996\u3002"]),harbour:e(["Harbour","\u6D77\u6E2F"],["Quays and piers on the bay, with cogs and galleys, where goods and captives come and go.","\u6D77\u6E7E\u8FB9\u7684\u7801\u5934\u4E0E\u6808\u6865\uFF0C\u6CCA\u7740\u67EF\u514B\u8239\u4E0E\u6868\u5E06\u8239\uFF0C\u8D27\u7269\u4E0E\u4FD8\u864F\u7531\u6B64\u8FDB\u51FA\u3002"],["Daenerys's ships come into Slaver's Bay here: quays, hulls and gulls.","\u4E39\u59AE\u8389\u4E1D\u7684\u8239\u961F\u5728\u6B64\u9A76\u5165\u5974\u96B6\u6E7E\uFF1A\u7801\u5934\u3001\u8239\u8EAB\u4E0E\u6D77\u9E25\u3002"],"medium",["asos"],["Astapor lies on the bay and Daenerys arrives there by ship.","\u963F\u65AF\u5854\u6CE2\u6FD2\u4E34\u6D77\u6E7E\uFF0C\u4E39\u59AE\u8389\u4E1D\u4E58\u8239\u62B5\u8FBE\u3002"],["Layout, depth and the volume of shipping.","\u5E03\u5C40\u3001\u6C34\u6DF1\u4E0E\u822A\u8FD0\u89C4\u6A21\u3002"],["A straight quay with four piers and moving ships; all invented.","\u4E00\u9053\u7B14\u76F4\u5CB8\u58C1\u3001\u56DB\u5EA7\u6808\u6865\u4E0E\u5F80\u6765\u8239\u53EA\uFF1B\u5747\u4E3A\u81EA\u62DF\u3002"]),"brick-warrens":e(["Brick Warrens","\u7EA2\u7816\u8857\u5DF7"],["Dense, low red-brick houses with flat roofs and the odd dome, crowding between the pyramids.","\u4F4E\u77EE\u5BC6\u96C6\u7684\u7EA2\u7816\u5E73\u9876\u5C4B\uFF0C\u5076\u89C1\u5706\u9876\uFF0C\u6324\u5728\u91D1\u5B57\u5854\u4E4B\u95F4\u3002"],["Behind the pyramids lies a sea of low brick houses and dusty lanes.","\u91D1\u5B57\u5854\u80CC\u540E\uFF0C\u662F\u4F4E\u77EE\u7816\u5C4B\u4E0E\u5C18\u571F\u5C0F\u5DF7\u6C47\u6210\u7684\u4E00\u7247\u6D77\u3002"],"low",["asos","awoiaf"],["The whole city is built of red brick; its ordinary quarters are not described.","\u5168\u57CE\u4EE5\u7EA2\u7816\u5EFA\u6210\uFF1B\u5BFB\u5E38\u8857\u533A\u5E76\u65E0\u63CF\u5199\u3002"],["Everything about ordinary housing.","\u5E73\u6C11\u4F4F\u5B85\u7684\u4E00\u5207\u7EC6\u8282\u3002"],["Randomly placed generic houses in a red palette.","\u968F\u673A\u5E03\u7F6E\u7684\u666E\u901A\u623F\u5C4B\uFF0C\u7EDF\u4E00\u4E3A\u7EA2\u8272\u8C03\u3002"])}};export{p as default};
